#!/bin/zsh
# Build MorningstarAblesetBridge.app for this Mac (Command Line Tools are enough).
# Then: ./MorningstarAblesetBridge.app/Contents/MacOS/MorningstarAblesetBridge --selftest
set -e
cd "$(dirname "$0")"
VERSION=$(cat VERSION)
BUILT=$(date "+%b %d, %H:%M")
FEED="${UPDATE_FEED-https://raw.githubusercontent.com/jonpikereally/MorningstarAblesetBridge/main/updates/latest.json}"
cat > Sources/MorningstarAblesetBridge/Version.swift <<SWIFT
// Generated by build.sh — do not edit.
enum AppVersion {
    static let version = "$VERSION"
    static let built = "$BUILT"
    static let updateFeed = "$FEED"
}
SWIFT
CACHE="${TMPDIR:-/tmp}/mab-modcache"
mkdir -p "$CACHE" MorningstarAblesetBridge.app/Contents/MacOS
cp Resources/Info.plist MorningstarAblesetBridge.app/Contents/Info.plist
mkdir -p MorningstarAblesetBridge.app/Contents/Resources
cp Resources/AppIcon.icns MorningstarAblesetBridge.app/Contents/Resources/AppIcon.icns
/usr/libexec/PlistBuddy -c "Set :CFBundleShortVersionString $VERSION" MorningstarAblesetBridge.app/Contents/Info.plist
swiftc -O -target arm64-apple-macos13 -module-cache-path "$CACHE" -o MorningstarAblesetBridge.app/Contents/MacOS/MorningstarAblesetBridge Sources/MorningstarAblesetBridge/*.swift
# Dropbox tags every synced file (com.dropbox.attrs), and codesign refuses a
# bundle carrying them ("resource fork, Finder information, or similar detritus").
xattr -cr MorningstarAblesetBridge.app 2>/dev/null || true
codesign --force --sign - MorningstarAblesetBridge.app
echo "Built MorningstarAblesetBridge.app v$VERSION ($BUILT)"
